def check_inclusion(s, p):
    m, n = len(p), len(s)
    if m == 0 or n == 0 or m > n:
        return False
    p_count = [0] * 26
    s_count = [0] * 26
    for i in range(m):
        p_count[ord(p[i]) - ord('a')]
        s_count[ord(s[i]) - ord('a')]
    if p_count == s_count:
        return True
    for i in range(m, n):
        s_count[ord(s[i]) - ord('a')] += 1
        s_count[ord(s[i - m]) - ord('a')] -= 1
        if p_count == s_count:
            return True
    return False

